/* global Vue, FinanceDomain */
(() => {
    'use strict';
    const { createApp, ref, reactive, computed, watch, nextTick, onMounted, onUnmounted } = Vue;
    const D = FinanceDomain;
    const boot = JSON.parse(document.getElementById('finance-bootstrap').textContent);
    const strokes = {
        users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M13 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.9 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
        telegram:'M22 3L2 11l7 3 3 7 10-18 M9 14L22 3 M9 14l1 6 3-3',
        overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
        wallet:'M3 7h18v14H3z M3 7V3h15v4 M16 12h5v4h-5z',
        category:'M4 3h6v6H4z M17 3l4 7h-8z M7 14a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M15 15h6v6h-6z',
        tasks:'M8 5H4v17h16V5h-4 M8 2h8v5H8z M8 14l3 3 6-7',
        exchange:'M4 7h15l-4-4 M20 17H5l4 4 M4 7l4 4 M20 17l-4-4',
        plus:'M12 4v16 M4 12h16', close:'M5 5l14 14 M5 19L19 5', menu:'M4 5h16 M4 12h16 M4 19h16',
        right:'M5 12h14 M13 6l6 6-6 6', left:'M19 12H5 M11 6l-6 6 6 6',
        search:'M16 16l5 5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',
        down:'M12 3v18 M5 14l7 7 7-7', up:'M12 21V3 M5 10l7-7 7 7',
        calendar:'M3 5h18v16H3z M7 2v6 M17 2v6 M3 11h18',
        edit:'M14 4l6 6 M3 21l5-1L21 7l-5-5L3 15z', trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',
        check:'M4 12l5 5L20 5', logout:'M9 3H3v18h6 M11 12h11 M16 6l6 6-6 6',
        refresh:'M20 7a9 9 0 1 0 1 9 M20 2v6h-6', clock:'M12 7v5l4 3 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
        arrow:'M4 17l6-6 4 4 6-9 M15 6h5v5', lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',
    };
    const Icon = { props:['name'], computed:{ shape(){return strokes[this.name] || strokes.wallet;} }, template:'<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path :d="shape"/></svg>' };
    const Modal = {
        props:['open','title','busy','error','danger','confirmLabel'], emits:['close','save'], components:{Icon},
        setup(props,{emit}) {
            const element=ref(null); let previous;
            watch(()=>props.open,async value=>{ await nextTick(); if(value){previous=document.activeElement;element.value.showModal();(element.value.querySelector('input:not([type=hidden]):not(:disabled),select:not(:disabled),textarea:not(:disabled)')||element.value.querySelector('button[type=submit]'))?.focus();}else if(element.value?.open){element.value.close();previous?.focus();} });
            function onKeydown(event) {
                if (event.key !== 'Enter' || event.isComposing || event.keyCode === 229) return;
                if (event.target.tagName === 'BUTTON' || (event.target.tagName === 'TEXTAREA' && event.shiftKey)) return;
                event.preventDefault();
                if (!props.busy && !event.repeat) event.currentTarget.requestSubmit();
            }
            return {element, onKeydown, dismiss(){if(!props.busy)emit('close');}};
        },
        template:`<dialog ref="element" class="dialog" @cancel.prevent="dismiss" @click="$event.target === element && dismiss()" aria-labelledby="dialog-title"><form @keydown="onKeydown" @submit.prevent="!busy && $emit('save')"><div class="dialog-heading"><span class="dialog-symbol"><icon :name="danger?'trash':'edit'"/></span><button type="button" class="icon-button" aria-label="Закрити діалог" :disabled="busy" @click="dismiss"><icon name="close"/></button></div><h2 id="dialog-title">{{title}}</h2><div v-if="error" role="alert" class="notice error">{{error}}</div><fieldset :disabled="busy"><slot/></fieldset><div class="dialog-actions"><button class="button text" type="button" :disabled="busy" @click="dismiss">Скасувати</button><button :class="['button',danger?'danger':'primary']" type="submit" :disabled="busy"><span v-if="busy" class="spinner small"></span>{{busy ? (danger ? 'Видалення…' : 'Збереження…') : (confirmLabel || 'Підтвердити')}}</button></div></form></dialog>`,
    };
    const app = {
        components:{Icon, AppModal:Modal},
        setup() {
            const user=ref(boot.user), view=ref(D.route(location.pathname,boot.base));
            const state=reactive({years:[],months:[],categories:[],users:[],members:[],budgets:[],tasks:[],recent:[],transactions:{items:[],page:1,last_page:1,total:0,spent:0}});
            const loading=ref(false), ready=ref(false), saving=ref(false), error=ref(''), notice=ref('');
            const drawer=ref(false), account=ref(false), drawerEl=ref(null), menuEl=ref(null);
            const search=ref(''), sort=ref('desc'), categorySearch=ref(''), userSearch=ref(''), linking=ref(false);
            const filters=reactive({title:'',category_id:'',user_id:'',type:'',page:1});
            const selectedDate=ref(D.dateKey(new Date())), cursor=ref(new Date());
            const dialog=ref(null), form=reactive({}), formError=ref(''), analytics=ref(null), analyticsLoading=ref(false);
            const auth=reactive({email:boot.email || '',password:'',password_confirmation:''}), authError=ref(''), authMessage=ref('');
            const rates=reactive({cny_usdt:'',usdt_cny:'',usdt_uah:'',updated_at:null}), rateBusy=ref(false), rateError=ref('');
            const exchange=reactive({cny:100,usd:0,uah:0}), exchangeSource=ref('cny');
            let requestId=0, controller, toastTimer, analyticsController, analyticsId=0;
            const url=path=>boot.base.replace(/\/$/,'')+path;
            function flash(message){notice.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>notice.value='',5000);}
            async function api(path,options={}) {
                const response=await fetch(path.startsWith('http')?path:boot.api+'/'+path,{
                    credentials:'same-origin',...options,headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':boot.csrf,...options.headers},
                });
                let body;try{body=await response.json();}catch{body={};}
                if(!response.ok){
                    const message=response.status===419?'Сесія завершилась. Оновіть сторінку та увійдіть знову.':response.status===401?'Потрібно увійти в кабінет.':Object.values(body.errors||{}).flat().join(' ')||body.message||'Не вдалося виконати дію. Спробуйте ще раз.';
                    throw new Error(message);
                }
                return body;
            }
            function readLocation(){
                view.value=D.route(location.pathname,boot.base);
                const params=new URLSearchParams(location.search);
                for(const field of ['title','category_id','user_id','type'])filters[field]=params.get(field)||'';
                filters.page=Math.max(1,Number(params.get('page'))||1);
                const taskDate=location.pathname.match(/\/tasks\/(\d{4}-\d{2}-\d{2})/);
                const day=params.get('day')||taskDate?.[1]||D.dateKey(new Date());
                if(/^\d{4}-\d{2}-\d{2}$/.test(day)&&!Number.isNaN(new Date(day+'T12:00:00').getTime())){selectedDate.value=day;cursor.value=new Date(day+'T12:00:00');}
                document.title=(titles[view.value.name]||'Finance')+' — Finance';
            }
            const titles={home:'Огляд фінансів',year:'Річний бюджет',month:'Бюджет місяця',transactions:'Транзакції',categories:'Категорії',users:'Користувачі',tasks:'Задачі',exchange:'Калькулятор',login:'Вхід',forgot:'Відновлення пароля',reset:'Новий пароль'};
            const title=computed(()=>titles[view.value.name]||'Finance');
            const isAuth=computed(()=>!user.value || ['login','forgot','reset'].includes(view.value.name));
            const currentMonth=computed(()=>state.months.find(row=>row.id===view.value.id));
            const currentYear=computed(()=>state.years.find(row=>row.id===(view.value.name==='year'?view.value.id:currentMonth.value?.year_id)));
            const months=computed(()=>state.months.filter(row=>row.year_id===currentYear.value?.id));
            const periods=computed(()=>{
                const rows=view.value.name==='year'?months.value:state.years;
                const filtered=rows.filter(row=>String(row.name).toLocaleLowerCase('uk').includes(search.value.toLocaleLowerCase('uk')));
                return view.value.name==='year'?filtered:[...filtered].sort((a,b)=>sort.value==='desc'?Number(b.name)-Number(a.name):Number(a.name)-Number(b.name));
            });
            const summary=computed(()=>view.value.name==='month'?{budget:currentMonth.value?.budget||0,spent:currentMonth.value?.spent||0}:view.value.name==='year'?D.totals(months.value):D.totals(state.years));
            const remaining=computed(()=>summary.value.budget-summary.value.spent);
            const categories=computed(()=>state.categories.filter(row=>row.name.toLocaleLowerCase('uk').includes(categorySearch.value.toLocaleLowerCase('uk'))));
            const members=computed(()=>state.members.filter(member=>[member.name,member.email,member.telegram_id].filter(Boolean).join(' ').toLocaleLowerCase('uk').includes(userSearch.value.toLocaleLowerCase('uk'))));
            const availableCategories=computed(()=>dialog.value==='budget'&&!form.id?state.categories.filter(row=>!state.budgets.some(b=>b.category_id===row.id)):state.categories);
            const transactionCategories=computed(()=>form.id?state.categories:state.categories.filter(row=>state.budgets.some(b=>b.category_id===row.id)));
            const calendar=computed(()=>D.calendar(cursor.value));
            const calendarTitle=computed(()=>new Intl.DateTimeFormat('uk-UA',{month:'long',year:'numeric'}).format(cursor.value));
            const selectedDayTitle=computed(()=>new Intl.DateTimeFormat('uk-UA',{day:'numeric',month:'long',year:'numeric'}).format(new Date(selectedDate.value+'T12:00:00')));
            const completed=computed(()=>state.tasks.filter(row=>row.is_completed).length);
            const taskUsers=computed(()=>state.users.filter(row=>[2,3].includes(row.id)||state.tasks.some(task=>task.user_id===row.id)||row.id===user.value?.id));
            const nav=[{name:'home',path:'/',label:'Огляд',icon:'overview'},{name:'transactions',path:'/transactions',label:'Транзакції',icon:'wallet'},{name:'categories',path:'/categories',label:'Категорії',icon:'category'},{name:'users',path:'/users',label:'Користувачі',icon:'users'},{name:'tasks',path:'/tasks',label:'Задачі',icon:'tasks'},{name:'exchange',path:'/exchange',label:'Калькулятор',icon:'exchange'}];
            const activeNav=computed(()=>['year','month'].includes(view.value.name)?'home':view.value.name);
            async function load(){
                if(isAuth.value)return;
                const id=++requestId;controller?.abort();controller=new AbortController();loading.value=true;error.value='';
                const params=new URLSearchParams();
                if(view.value.name==='month')params.set('month_id',view.value.id);
                if(view.value.name==='year')params.set('year_id',view.value.id);
                if(['month','transactions'].includes(view.value.name))for(const [key,value]of Object.entries(filters))if(value)params.set(key,value);
                params.set('date',selectedDate.value);
                try{
                    const results=await Promise.all([api('data?'+params,{signal:controller.signal}),view.value.name==='users'?api('users',{signal:controller.signal}):Promise.resolve(null)]);
                    if(id===requestId){Object.assign(state,results[0]);if(results[1])state.members=results[1].users;ready.value=true;}
                }
                catch(e){if(e.name!=='AbortError'&&id===requestId)error.value=e.message;}
                finally{if(id===requestId)loading.value=false;}
            }
            function switchYear(event) {
                const yearId = Number(event.target.value);
                const monthNumber = currentMonth.value?.number;
                const target = state.months.find(month => Number(month.year_id) === yearId && Number(month.number) === Number(monthNumber));
                if (target) {
                    navigate('/month/' + target.id);
                } else {
                    event.target.value = currentYear.value?.id || '';
                    error.value = 'В обраному році немає цього місяця.';
                }
            }
            async function navigate(path){
                if(saving.value)return;
                ready.value=false;history.pushState({},'',url(path));readLocation();drawer.value=false;account.value=false;search.value='';error.value='';
                window.scrollTo({top:0,behavior:'instant'});await load();
                if(view.value.name==='exchange'&&!rates.updated_at)loadRates();
                nextTick(()=>document.getElementById('page-heading')?.focus());
            }
            function applyFilters(){filters.page=1;syncFilters();load();}
            function syncFilters(){const params=new URLSearchParams();for(const [key,value]of Object.entries(filters))if(value&&!(key==='page'&&value===1))params.set(key,value);history.replaceState({},'',location.pathname+(params.size?'?'+params:''));}
            function resetFilters(){Object.assign(filters,{title:'',category_id:'',user_id:'',type:'',page:1});syncFilters();load();}
            function page(delta){filters.page+=delta;syncFilters();load();}
            function openDialog(kind,row={}){
                for(const key of Object.keys(form))delete form[key];formError.value='';analytics.value=null;
                if(kind==='year')Object.assign(form,{year:new Date().getFullYear()});
                if(kind==='category')Object.assign(form,{name:''},row);
                if(kind==='userTelegram')Object.assign(form,{id:row.id,name:row.name,telegram_id:row.telegram_id||''});
                if(kind==='transaction')Object.assign(form,{month_id:currentMonth.value?.id,category_id:state.budgets[0]?.category_id||'',title:'',amount:'',type:'card'},row,{created_at:row.id?row.created_at_local:D.localTime(new Date(),boot.timezone||'Europe/Kyiv')});
                if(kind==='budget')Object.assign(form,{month_id:currentMonth.value?.id,category_id:'',budget:''},row);
                if(kind==='task')Object.assign(form,{user_id:row.user_id||user.value.id,description:'',priority:'middle',task_date:selectedDate.value,task_time:''});
                if(kind==='deleteTransaction'||kind==='deleteTask')Object.assign(form,row);
                dialog.value=kind;
                if(kind==='budget'&&form.category_id)loadAnalytics();
            }
            function closeDialog(){if(!saving.value){dialog.value=null;analyticsController?.abort();analyticsId++;}}
            const dialogTitle=computed(()=>({year:'Додати рік',userTelegram:'Прив’язати Telegram ID',category:form.id?'Редагувати категорію':'Нова категорія',transaction:form.id?'Редагувати транзакцію':'Додати витрату',budget:form.id?'Змінити бюджет':'Додати бюджет',task:'Нова задача',deleteTransaction:'Видалити транзакцію?',deleteTask:'Видалити задачу?'})[dialog.value]||'');
            async function save(){
                if(saving.value)return;saving.value=true;formError.value='';
                const endpoints={userTelegram:['users/'+form.id+'/telegram','PUT'],year:['years','POST'],category:[form.id?'categories/'+form.id:'categories',form.id?'PUT':'POST'],budget:['budgets','POST'],transaction:[form.id?'transactions/'+form.id:'transactions',form.id?'PUT':'POST'],task:['tasks','POST'],deleteTransaction:['transactions/'+form.id,'DELETE'],deleteTask:['tasks/'+form.id,'DELETE']};
                try{const [endpoint,method]=endpoints[dialog.value];const result=await api(endpoint,{method,body:method==='DELETE'?undefined:JSON.stringify(form)});dialog.value=null;flash(result.message);await load();}
                catch(e){formError.value=e.message;}finally{saving.value=false;}
            }
            async function toggleTask(task){if(saving.value)return;saving.value=true;try{const result=await api('tasks/'+task.id,{method:'PATCH'});flash(result.message);await load();}catch(e){error.value=e.message;}finally{saving.value=false;}}
            async function loadAnalytics(){
                const id=++analyticsId;analyticsController?.abort();analytics.value=null;
                if(dialog.value!=='budget'||!form.category_id||!currentYear.value){analyticsLoading.value=false;return;}
                analyticsController=new AbortController();analyticsLoading.value=true;
                try{const result=await api('analytics?'+new URLSearchParams({year_id:currentYear.value.id,category_id:form.category_id}),{signal:analyticsController.signal});if(id===analyticsId)analytics.value=result.amount;}
                catch(e){if(e.name!=='AbortError'&&id===analyticsId)formError.value='Не вдалося завантажити рекомендацію. Бюджет можна ввести вручну.';}
                finally{if(id===analyticsId)analyticsLoading.value=false;}
            }
            function selectDay(day){navigate('/tasks/'+day+'?day='+day);}
            function shiftCalendar(delta){const next=new Date(cursor.value.getFullYear(),cursor.value.getMonth()+delta,1,12);selectDay(D.dateKey(next));}
            function tasksFor(id){return state.tasks.filter(task=>task.user_id===id);}
            const priorityLabel=value=>({high:'Високий',middle:'Середній',low:'Низький'})[value]||value;
            async function loadRates(){if(rateBusy.value)return;rateBusy.value=true;rateError.value='';try{Object.assign(rates,await api('rates'));recalculate(exchangeSource.value);}catch(e){rateError.value=e.message;}finally{rateBusy.value=false;}}
            function recalculate(from){exchangeSource.value=from;const result=D.convert(exchange[from],from,rates);if(result)for(const key of ['cny','usd','uah'])if(key!==from)exchange[key]=Number(result[key].toFixed(2));}
            async function openTelegram(member=user.value){
                if(linking.value)return;
                linking.value=true;error.value='';
                const popup=window.open('','_blank');
                if(popup)popup.opener=null;
                try{
                    const result=await api('users/'+member.id+'/telegram-link',{method:'POST'});
                    if(popup)popup.location.replace(result.url);else window.location.assign(result.url);
                }catch(e){popup?.close();error.value=e.message;}finally{linking.value=false;account.value=false;}
            }
            async function logout(){if(saving.value)return;saving.value=true;try{const result=await api('logout',{method:'POST'});location.assign(result.url);}catch(e){error.value=e.message;saving.value=false;}}
            async function submitAuth(){
                if(saving.value)return;saving.value=true;authError.value='';authMessage.value='';
                const mode=view.value.name==='forgot'?'forgot':view.value.name==='reset'?'reset':'login';
                try{const result=await api(url(mode==='forgot'?'/forgot-password':mode==='reset'?'/reset-password':'/login'),{method:'POST',body:JSON.stringify({...auth,token:boot.resetToken})});
                    if(mode==='login')location.assign(result.url||url('/'));else if(mode==='reset'){authMessage.value=result.message;setTimeout(()=>location.assign(url('/login')),1200);}else authMessage.value=result.message;
                }catch(e){authError.value=e.message;}finally{saving.value=false;}
            }
            function refreshTelegramStatus(){
                if(!document.hidden&&view.value.name==='users'&&!isAuth.value&&!loading.value&&!saving.value)load();
            }
            function onPop(){ready.value=false;readLocation();drawer.value=false;load();if(view.value.name==='exchange'&&!rates.updated_at)loadRates();}
            function keydown(e){if(e.key==='Escape'){drawer.value=false;account.value=false;}
                if(e.key==='Tab'&&drawer.value){const nodes=[...drawerEl.value.querySelectorAll('a,button')].filter(node=>node.offsetParent!==null);const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
            }
            watch(drawer,async open=>{document.body.classList.toggle('drawer-open',open);await nextTick();if(open)drawerEl.value?.querySelector('a,button')?.focus();else menuEl.value?.focus();});
            watch(()=>form.category_id,()=>{if(dialog.value==='budget')loadAnalytics();});
            onMounted(()=>{readLocation();load();if(!isAuth.value&&view.value.name==='exchange')loadRates();window.addEventListener('popstate',onPop);document.addEventListener('keydown',keydown);document.addEventListener('visibilitychange',refreshTelegramStatus);});
            onUnmounted(()=>{controller?.abort();analyticsController?.abort();clearTimeout(toastTimer);window.removeEventListener('popstate',onPop);document.removeEventListener('keydown',keydown);document.removeEventListener('visibilitychange',refreshTelegramStatus);document.body.classList.remove('drawer-open');});
            return {boot,user,view,state,loading,ready,saving,error,notice,drawer,account,drawerEl,menuEl,search,sort,categorySearch,userSearch,linking,members,filters,selectedDate,cursor,dialog,form,formError,analytics,analyticsLoading,auth,authError,authMessage,rates,rateBusy,rateError,exchange,nav,title,isAuth,activeNav,currentMonth,currentYear,months,periods,summary,remaining,categories,availableCategories,transactionCategories,calendar,calendarTitle,selectedDayTitle,completed,taskUsers,dialogTitle,
                url,navigate,switchYear,load,applyFilters,resetFilters,page,openDialog,closeDialog,save,toggleTask,loadAnalytics,selectDay,shiftCalendar,tasksFor,priorityLabel,loadRates,recalculate,openTelegram,logout,submitAuth,money:D.money,progress:D.progress,today:D.dateKey(new Date()),dateLabel:value=>new Intl.DateTimeFormat('uk-UA',{timeZone:boot.timezone||'Europe/Kyiv',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(value)),initial:computed(()=>(user.value?.name||user.value?.email||'F').charAt(0).toUpperCase())};
        },
        template: `
        <div v-if="isAuth" class="auth-page">
            <section class="auth-story"><a class="brand" :href="url('/login')" @click.prevent="navigate('/login')"><span class="brand-icon"><icon name="wallet"/></span>Finance<span class="brand-dot"></span></a><div class="auth-story-body"><span class="eyebrow">ПРОСТІР ДЛЯ ВАШИХ ПЛАНІВ</span><h1>Більше ясності.<br>Більше можливостей.</h1><p>Плануйте бюджет, стежте за витратами та залишайте більше місця для важливого.</p><div class="auth-illustration" aria-hidden="true"><div class="illustration-orbit"></div><div class="illustration-card"><span class="illustration-icon"><icon name="wallet"/></span><span>Ваші фінанси</span><strong>Під контролем</strong><div class="illustration-bars"><i></i><i></i><i></i><i></i><i></i><i></i></div></div><span class="illustration-check"><icon name="check"/></span></div></div><span class="auth-caption">Особистий фінансовий кабінет</span></section>
            <section class="auth-form-side"><form class="auth-form" @submit.prevent="submitAuth"><span class="surface-icon"><icon name="lock"/></span><span class="eyebrow">РАДІ ВАС БАЧИТИ</span><h2>{{view.name==='forgot'?'Відновити пароль':view.name==='reset'?'Новий пароль':'Вітаємо знову'}}</h2><p class="muted">{{view.name==='forgot'?'Введіть пошту, і ми надішлемо посилання для відновлення.':view.name==='reset'?'Створіть новий пароль для свого кабінету.':'Увійдіть, щоб продовжити свої фінансові плани.'}}</p><div v-if="authError" class="notice error" role="alert">{{authError}}</div><div v-if="authMessage" class="notice success" role="status">{{authMessage}}</div><fieldset :disabled="saving"><label class="field">Електронна пошта<input v-model="auth.email" type="email" autocomplete="username" placeholder="name@example.com" required></label><template v-if="view.name!=='forgot'"><label class="field">Пароль<input v-model="auth.password" type="password" :autocomplete="view.name==='reset'?'new-password':'current-password'" :minlength="view.name==='reset'?5:undefined" required placeholder="Введіть пароль"></label><label v-if="view.name==='reset'" class="field">Підтвердження пароля<input v-model="auth.password_confirmation" type="password" autocomplete="new-password" minlength="5" required></label></template><a v-if="!['forgot','reset'].includes(view.name)" class="auth-forgot" :href="url('/forgot-password')" @click.prevent="navigate('/forgot-password')">Забули пароль?</a><button class="button primary auth-submit" :disabled="saving"><span v-if="saving" class="spinner small"></span>{{saving?'Зачекайте…':view.name==='forgot'?'Надіслати посилання':view.name==='reset'?'Зберегти пароль':'Увійти в кабінет'}}<icon v-if="!saving" name="right"/></button></fieldset><a v-if="['forgot','reset'].includes(view.name)" class="auth-back" :href="url('/login')" @click.prevent="navigate('/login')"><icon name="left"/>Повернутися до входу</a></form></section>
        </div>
        <div v-else class="workspace">
            <a href="#main-content" class="skip-link">Перейти до вмісту</a>
            <div v-if="drawer" class="drawer-scrim" @click="drawer=false"></div>
            <aside ref="drawerEl" :class="['sidebar',{open:drawer}]" id="navigation" aria-label="Головне меню"><a class="brand" :href="url('/')" @click.prevent="navigate('/')"><span class="brand-icon"><icon name="wallet"/></span>Finance<span class="brand-dot"></span></a><button class="icon-button close-drawer" aria-label="Закрити меню" @click="drawer=false"><icon name="close"/></button><div class="nav-caption">ОСОБИСТИЙ ПРОСТІР</div><nav><a v-for="item in nav" :key="item.name" :href="url(item.path)" :class="['nav-item',{active:activeNav===item.name}]" :aria-current="activeNav===item.name?'page':null" @click.prevent="navigate(item.path)"><icon :name="item.icon"/><span>{{item.label}}</span><span v-if="activeNav===item.name" class="nav-dot"></span></a></nav><div class="sidebar-bottom"><div class="sidebar-note"><span class="note-symbol"><icon name="arrow"/></span><strong>Маленькі кроки.<br>Великі плани.</strong><p>Кожна запланована витрата наближає до фінансової ясності.</p></div><button class="nav-item logout" :disabled="saving" @click="logout"><icon name="logout"/><span>Вийти з кабінету</span></button></div></aside>
            <div class="workspace-body"><header class="topbar"><div class="topbar-left"><button ref="menuEl" class="icon-button mobile-menu" @click="drawer=true" aria-label="Відкрити меню" :aria-expanded="drawer" aria-controls="navigation"><icon name="menu"/></button><span class="breadcrumb">Особистий кабінет<span>/</span><strong>{{title}}</strong></span></div><div class="topbar-right"><button class="button tonal topbar-telegram" :disabled="linking" @click="openTelegram()"><icon name="telegram"/>{{linking?'Зачекайте…':'Відкрити Telegram-бота'}}</button><span class="today-label"><icon name="calendar"/>{{new Intl.DateTimeFormat('uk-UA',{day:'numeric',month:'long'}).format(new Date())}}</span><div class="profile-wrap"><button class="profile" @click="account=!account" :aria-expanded="account" aria-controls="profile-menu"><span class="avatar">{{initial}}</span><span class="profile-copy"><strong>{{user.name||'Користувач'}}</strong><small>Особистий акаунт</small></span></button><button v-if="account" class="profile-scrim" aria-label="Закрити профіль" @click="account=false"></button><div v-if="account" class="profile-menu" id="profile-menu"><strong>{{user.name}}</strong><p>{{user.email}}</p><button class="button text profile-telegram" :disabled="linking" @click="openTelegram()"><icon name="telegram"/>Відкрити Telegram-бота</button><button class="button text" :disabled="saving" @click="logout"><icon name="logout"/>Вийти</button></div></div></div></header>
            <main id="main-content" :aria-busy="loading"><div v-if="loading" class="loading-line" role="status"><span class="visually-hidden">Завантаження даних</span></div><div v-if="error" class="notice error page-error" role="alert"><span>{{error}}</span><button class="button text" :disabled="loading" @click="load">Спробувати ще</button></div>
            <div class="page-intro"><div><span class="eyebrow">{{view.name==='home'?'ВАША ФІНАНСОВА КАРТИНА':view.name==='tasks'?'ПРОСТІР ДЛЯ ВАЖЛИВОГО':'ВАШІ ФІНАНСИ, ВАШІ ПРАВИЛА'}}</span><h1 id="page-heading" tabindex="-1">{{view.name==='year'?'Бюджет на '+(currentYear?.name||'…')+' рік':view.name==='month'?(currentMonth?.name||'Бюджет місяця')+' '+(currentYear?.name||''):title}}<span v-if="view.name==='home'" class="heading-dot">.</span></h1><p class="muted">{{({home:'Плануйте впевнено. Витрачайте усвідомлено.',year:'Кожен місяць — ще один крок до фінансової ясності.',month:'Керуйте витратами та бюджетами категорій.',transactions:'Усі витрати, деталі та історія в одному місці.',categories:'Зручний порядок у ваших щоденних витратах.',users:'Акаунти кабінету та прив’язка Telegram для статистики й витрат.',tasks:'Звільніть думки для важливого — плани залиште тут.',exchange:'Швидкий перерахунок CNY, USDT та гривні.'})[view.name]}}</p></div><div class="intro-actions"><button v-if="view.name==='home'" class="button primary" :disabled="loading" @click="openDialog('year')"><icon name="plus"/>Додати рік</button><button v-if="view.name==='categories'" class="button primary" :disabled="loading" @click="openDialog('category')"><icon name="plus"/>Нова категорія</button><button v-if="view.name==='month'" class="button primary" :disabled="loading||!state.budgets.length" @click="openDialog('transaction')"><icon name="plus"/>Додати витрату</button><button v-if="view.name==='tasks'" class="button primary" :disabled="loading" @click="openDialog('task')"><icon name="plus"/>Нова задача</button><button v-if="view.name==='exchange'" class="button outlined" :disabled="rateBusy" @click="loadRates"><icon name="refresh"/>{{rateBusy?'Оновлення…':'Оновити курси'}}</button><a v-if="view.name==='year'" :href="url('/')" class="button outlined" @click.prevent="navigate('/')"><icon name="left"/>До огляду</a></div></div>
            <div v-if="loading&&!ready" class="skeleton-layout" aria-label="Завантаження"><div v-for="n in 3" :key="n" class="skeleton"></div><div class="skeleton wide"></div></div>
            <template v-if="ready">
            <template v-if="['home','year','month'].includes(view.name)"><section class="stats-grid" aria-label="Підсумок бюджету"><article class="stat-card budget-stat"><div class="stat-label"><span class="stat-icon"><icon name="wallet"/></span><span>{{view.name==='home'?'Загальний бюджет':'Запланований бюджет'}}</span><span class="stat-period">{{view.name==='home'?'За всі роки':currentYear?.name}}</span></div><strong class="stat-amount">{{money(summary.budget)}}<small>грн</small></strong><div class="stat-foot"><span>Ваш план на {{view.name==='month'?'місяць':view.name==='year'?'рік':'всі періоди'}}</span><icon name="arrow"/></div></article><article class="stat-card"><div class="stat-label"><span class="stat-icon expense-icon"><icon name="down"/></span><span>Витрачено</span></div><strong class="stat-amount">{{money(summary.spent)}}<small>грн</small></strong><div class="stat-foot"><span>Фактичні витрати за період</span><span class="tiny-pill">{{summary.budget>0?Math.round(summary.spent/summary.budget*100):'—'}}{{summary.budget>0?'% бюджету':''}}</span></div></article><article class="stat-card"><div class="stat-label"><span class="stat-icon balance-icon"><icon name="arrow"/></span><span>{{remaining>=0?'Залишок бюджету':'Перевищення бюджету'}}</span></div><strong :class="['stat-amount',{negative:remaining<0}]">{{money(Math.abs(remaining))}}<small>грн</small></strong><div class="stat-foot"><span>{{remaining>=0?'Місце для ваших планів':'Витрати перевищують план'}}</span><span :class="['status-dot',{danger:remaining<0}]"></span></div></article></section></template>
            <template v-if="['home','year'].includes(view.name)"><nav v-if="view.name==='year'" class="chips year-chips" aria-label="Оберіть рік"><a v-for="year in state.years" :key="year.id" :href="url('/year/'+year.id)" :class="['chip',{selected:year.id===currentYear?.id}]" :aria-current="year.id===currentYear?.id?'page':null" @click.prevent="navigate('/year/'+year.id)">{{year.name}}</a></nav><div :class="['overview-columns',{'full-width':view.name==='year'}]"><section class="period-section"><div class="section-heading"><div><h2>{{view.name==='home'?'Бюджети за роками':'Бюджети за місяцями'}}</h2><p>{{view.name==='home'?'Від великих планів — до щоденних рішень':'Оберіть місяць, щоб перейти до витрат'}}</p></div><label v-if="view.name==='home'" class="sort-select"><span class="visually-hidden">Сортувати роки</span><select v-model="sort"><option value="desc">Спочатку нові</option><option value="asc">Спочатку старі</option></select></label></div><label v-if="state.years.length" class="search-field"><icon name="search"/><input v-model="search" type="search" :placeholder="view.name==='home'?'Знайти рік…':'Знайти місяць…'" :aria-label="view.name==='home'?'Знайти рік':'Знайти місяць'"></label><div class="period-grid"><a v-for="period in periods" :key="period.id" :href="url((view.name==='home'?'/year/':'/month/')+period.id)" :class="['period-card',{'period-overdrawn':period.spent>period.budget}]" @click.prevent="navigate((view.name==='home'?'/year/':'/month/')+period.id)"><div class="period-card-top"><span class="surface-icon"><icon name="calendar"/></span><span :class="['badge',period.spent>period.budget?'warning':'blue']">{{period.spent>period.budget?'Перевищено':'У межах плану'}}</span></div><h3>{{period.name}}</h3><span class="label-small">Запланований бюджет</span><strong class="period-amount">{{money(period.budget)}} <small>грн</small></strong><div class="progress-caption"><span>Витрачено</span><strong>{{money(period.spent)}} грн</strong></div><div :class="['progress-track',{over:period.spent>period.budget}]" role="progressbar" :aria-label="'Використано бюджет: '+period.name" :aria-valuenow="Math.round(progress(period))" aria-valuemin="0" aria-valuemax="100"><span :style="{width:progress(period)+'%'}"></span></div><div class="period-bottom"><span>{{period.budget>=period.spent?'Залишок':'Перевищення'}} {{money(Math.abs(period.budget-period.spent))}} грн</span><span class="round-arrow"><icon name="right"/></span></div></a></div><div v-if="!periods.length" class="empty-state"><span class="empty-icon"><icon name="calendar"/></span><h3>{{search?'Нічого не знайдено':'Перший крок до ваших планів'}}</h3><p>{{search?'Спробуйте інший запит.':'Створіть рік, щоб почати планувати місячні бюджети.'}}</p><button v-if="search" class="button tonal" @click="search=''">Скинути пошук</button><button v-else class="button primary" @click="openDialog('year')"><icon name="plus"/>Створити рік</button></div></section><aside v-if="view.name==='home'" class="panel recent-panel"><div class="section-heading"><div><h2>Останні витрати</h2><p>Ваша фінансова історія</p></div><span class="counter">{{state.recent.length}}</span></div><article v-for="row in state.recent" :key="row.id" class="recent-row"><span class="recent-icon"><icon name="wallet"/></span><div class="recent-copy"><h3>{{row.title}}</h3><p>{{row.category||'Без категорії'}}</p><time>{{dateLabel(row.created_at)}}</time></div><strong>−{{money(row.amount)}}<small>грн</small></strong></article><div v-if="!state.recent.length" class="empty-state compact"><icon name="wallet"/><h3>Витрат поки немає</h3><p>Відкрийте бюджет місяця та додайте першу транзакцію.</p></div><a class="panel-link" :href="url('/transactions')" @click.prevent="navigate('/transactions')">Усі транзакції<icon name="right"/></a></aside></div></template>
            <template v-if="['month','transactions'].includes(view.name)"><nav v-if="view.name==='month'" class="period-navigation" aria-label="Рік та місяць"><label class="year-picker"><span class="visually-hidden">Оберіть рік</span><select :value="currentYear?.id" :disabled="loading||saving" @change="switchYear"><option v-for="year in state.years" :value="year.id" :key="year.id">{{year.name}}</option></select></label><div class="chips"><a v-for="month in months" :key="month.id" :href="url('/month/'+month.id)" :class="['chip',{selected:month.id===currentMonth?.id}]" :aria-current="month.id===currentMonth?.id?'page':null" @click.prevent="navigate('/month/'+month.id)">{{month.name}}</a></div></nav><div :class="['transactions-columns',{'full-width':view.name==='transactions'}]"><section class="panel transaction-panel"><div class="section-heading"><div><h2>Історія витрат</h2><p>{{state.transactions.total}} транзакцій · {{money(state.transactions.spent)}} грн за фільтром</p></div><div class="transaction-heading-actions"><button v-if="view.name==='month'" class="button primary" :disabled="loading||!state.budgets.length" @click="openDialog('transaction')"><icon name="plus"/>Додати транзакцію</button><span class="surface-icon"><icon name="wallet"/></span></div></div><form class="filters" @submit.prevent="applyFilters"><label class="search-field filter-search"><icon name="search"/><input v-model="filters.title" type="search" placeholder="Пошук за описом" aria-label="Опис транзакції"></label><label><span class="visually-hidden">Категорія</span><select v-model="filters.category_id"><option value="">Усі категорії</option><option v-for="category in state.categories" :key="category.id" :value="category.id">{{category.name}}</option></select></label><label><span class="visually-hidden">Автор</span><select v-model="filters.user_id"><option value="">Усі автори</option><option v-for="author in state.users" :key="author.id" :value="author.id">{{author.name}}</option></select></label><label><span class="visually-hidden">Спосіб оплати</span><select v-model="filters.type"><option value="">Усі способи</option><option value="card">Картка</option><option value="cash">Готівка</option></select></label><button class="button tonal" :disabled="loading">Застосувати</button><button class="icon-button" type="button" aria-label="Скинути фільтри" :disabled="loading" @click="resetFilters"><icon name="close"/></button></form><div v-if="view.name==='month'" class="month-transaction-list"><article v-for="row in state.transactions.items" :key="row.id" class="month-transaction"><span class="month-transaction-symbol"><icon :name="row.type==='card'?'wallet':'exchange'"/></span><div class="month-transaction-content"><button class="month-transaction-title" @click="openDialog('transaction',row)">{{row.title}}</button><div class="month-transaction-meta"><span class="month-category">{{row.category||'Без категорії'}}</span><span class="month-payment">{{row.type==='card'?'Картка':'Готівка'}}</span></div><div class="month-transaction-author"><span>{{row.author||'—'}}</span></div></div><div class="month-transaction-end"><div class="month-transaction-value"><time class="transaction-date-badge" :datetime="row.created_at"><icon name="calendar"/>{{dateLabel(row.created_at)}}</time><strong class="month-transaction-amount">−{{money(row.amount)}} <small>грн</small></strong></div><div class="row-actions"><button class="icon-button" :aria-label="'Редагувати: '+row.title" @click="openDialog('transaction',row)"><icon name="edit"/></button><button class="icon-button danger-text" :aria-label="'Видалити: '+row.title" @click="openDialog('deleteTransaction',row)"><icon name="trash"/></button></div></div></article></div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>Витрата</th><th>Категорія</th><th>Сума</th><th>Оплата</th><th>Автор / дата</th><th><span class="visually-hidden">Дії</span></th></tr></thead><tbody><tr v-for="row in state.transactions.items" :key="row.id"><td><button class="transaction-name" @click="openDialog('transaction',row)">{{row.title}}</button></td><td><span class="category-label">{{row.category||'Без категорії'}}</span></td><td class="amount-cell">{{money(row.amount)}}<small>грн</small></td><td><span class="payment-label">{{row.type==='card'?'Картка':'Готівка'}}</span></td><td class="author-cell"><span>{{row.author||'—'}}</span><time>{{dateLabel(row.created_at)}}</time></td><td><div class="row-actions"><button class="icon-button" :aria-label="'Редагувати: '+row.title" @click="openDialog('transaction',row)"><icon name="edit"/></button><button class="icon-button danger-text" :aria-label="'Видалити: '+row.title" @click="openDialog('deleteTransaction',row)"><icon name="trash"/></button></div></td></tr></tbody></table></div><div v-if="!state.transactions.items.length" class="empty-state"><span class="empty-icon"><icon name="wallet"/></span><h3>Транзакцій не знайдено</h3><p>Змініть фільтри або додайте витрату в бюджеті місяця.</p><button class="button text" @click="resetFilters">Скинути фільтри</button></div><div v-if="view.name!=='month'" class="pagination"><span>Сторінка {{state.transactions.page}} з {{state.transactions.last_page}}</span><div><button class="icon-button" aria-label="Попередня сторінка" :disabled="loading||state.transactions.page<=1" @click="page(-1)"><icon name="left"/></button><button class="icon-button" aria-label="Наступна сторінка" :disabled="loading||state.transactions.page>=state.transactions.last_page" @click="page(1)"><icon name="right"/></button></div></div></section><aside v-if="view.name==='month'" class="panel budgets-panel"><div class="section-heading"><div><h2>Бюджети категорій</h2><p>План і фактичні витрати</p></div><button class="icon-button tonal" aria-label="Додати бюджет категорії" @click="openDialog('budget')"><icon name="plus"/></button></div><button v-for="budget in state.budgets" :key="budget.id" :class="['budget-row',{'budget-overdrawn':budget.spent>budget.budget}]" @click="openDialog('budget',budget)"><div><strong>{{budget.name}}</strong><icon name="edit"/></div><p><span><span class="budget-spent-amount">{{money(budget.spent)}}</span> <small>витрачено</small></span><strong class="budget-planned-amount">{{money(budget.budget)}} грн</strong></p><div :class="['progress-track',{over:budget.spent>budget.budget}]"><span :style="{width:progress(budget)+'%'}"></span></div><span v-if="budget.spent>budget.budget" class="budget-warning">Перевищення {{money(budget.spent-budget.budget)}} грн</span></button><div v-if="!state.budgets.length" class="empty-state compact"><icon name="category"/><h3>Спочатку — бюджет</h3><p>Додайте категорію та її бюджет, щоб записувати витрати.</p><button class="button tonal" @click="openDialog('budget')">Додати бюджет</button></div></aside></div></template>
            <section v-if="view.name==='users'" class="panel users-panel"><div class="section-heading"><div><h2>Користувачі кабінету</h2><p>Прив’яжіть Telegram вручну або відкрийте бота за одноразовим посиланням.</p></div><label class="search-field"><icon name="search"/><input v-model="userSearch" type="search" placeholder="Знайти користувача…" aria-label="Знайти користувача"></label></div><div class="users-grid"><article v-for="member in members" :key="member.id" class="user-card"><div class="user-card-heading"><span class="avatar">{{(member.name||member.email||'?').charAt(0).toUpperCase()}}</span><div><h3>{{member.name||'Користувач'}}<span v-if="member.is_self" class="user-self-label">Ви</span></h3><p>{{member.email}}</p><small>ID користувача: {{member.id}}</small></div></div><div :class="['telegram-status',{connected:member.telegram_id}]"><icon name="telegram"/><div><strong>{{member.telegram_id?'Telegram прив’язаний':'Telegram не прив’язаний'}}</strong><span>{{member.telegram_id?'ID: '+member.telegram_id:'Статистика та нові витрати просто в чаті'}}</span></div></div><div class="user-card-actions"><button class="button outlined" :disabled="saving" @click="openDialog('userTelegram',member)"><icon name="edit"/>{{member.telegram_id?'Змінити Telegram ID':'Ввести Telegram ID'}}</button><button class="button primary" :disabled="linking" @click="openTelegram(member)"><icon name="telegram"/>Відкрити Telegram-бота</button></div></article></div><div v-if="!members.length" class="empty-state"><icon name="users"/><h3>Нікого не знайдено</h3><p>Спробуйте інший пошуковий запит.</p></div><p class="users-help">Посилання діє 10 хвилин. Відкрийте Telegram і натисніть «Старт» — бот автоматично прив’яже акаунт. Статус оновиться після повернення в кабінет.</p><button class="button text" :disabled="loading" @click="load"><icon name="refresh"/>Оновити список</button></section>
            <section v-if="view.name==='categories'" class="panel category-panel"><div class="section-heading"><div><h2>Ваші категорії</h2><p>{{state.categories.length}} категорій для щоденних витрат</p></div><label class="search-field"><icon name="search"/><input v-model="categorySearch" type="search" placeholder="Знайти категорію…" aria-label="Знайти категорію"></label></div><div class="category-grid"><article v-for="category in categories" :key="category.id" class="category-card"><div class="category-card-heading"><span class="category-icon"><icon name="category"/></span><button class="icon-button" :aria-label="'Редагувати категорію: '+category.name" :disabled="saving" @click="openDialog('category',category)"><icon name="edit"/></button></div><h3><button class="category-name-button" @click="openDialog('category',category)">{{category.name}}</button></h3><span class="category-card-note">Категорія витрат</span></article><button v-if="!categorySearch" class="category-card add-category" @click="openDialog('category')"><span class="category-icon"><icon name="plus"/></span><strong>Нова категорія</strong><span>Додайте більше порядку</span></button></div><div v-if="!categories.length&&categorySearch" class="empty-state"><icon name="search"/><h3>Нічого не знайдено</h3><p>Спробуйте іншу назву категорії.</p><button class="button text" @click="categorySearch=''">Скинути пошук</button></div></section>
            <template v-if="view.name==='tasks'"><div class="tasks-overview"><div><span class="surface-icon"><icon name="tasks"/></span><div><strong>{{completed}} із {{state.tasks.length}}</strong><span>задач виконано за день</span></div></div><div class="task-progress"><div class="progress-track"><span :style="{width:(state.tasks.length?completed/state.tasks.length*100:0)+'%'}"></span></div><span>{{selectedDayTitle}}</span></div></div><div class="tasks-layout"><aside class="panel calendar-panel"><div class="calendar-header"><button class="icon-button" aria-label="Попередній місяць" @click="shiftCalendar(-1)"><icon name="left"/></button><h2>{{calendarTitle}}</h2><button class="icon-button" aria-label="Наступний місяць" @click="shiftCalendar(1)"><icon name="right"/></button></div><div class="calendar-grid"><span v-for="day in ['Пн','Вт','Ср','Чт','Пт','Сб','Нд']" :key="day" class="weekday">{{day}}</span><button v-for="day in calendar" :key="day.key" :class="['calendar-day',{outside:day.outside,selected:day.key===selectedDate,today:day.key===today}]" :aria-label="day.key" :aria-pressed="day.key===selectedDate" @click="selectDay(day.key)">{{day.day}}</button></div><button class="button text calendar-today" @click="selectDay(today)">Сьогодні</button><label class="field calendar-date">Перейти до дати<input type="date" :value="selectedDate" required @change="$event.target.value && selectDay($event.target.value)"></label></aside><section class="task-boards"><article v-for="person in taskUsers" :key="person.id" class="panel task-board"><div class="section-heading"><div class="person-title"><span class="avatar">{{(person.name||'?').charAt(0)}}</span><div><h2>{{person.name}}</h2><p>{{tasksFor(person.id).length}} задач на день</p></div></div><button class="icon-button tonal" :aria-label="'Додати задачу: '+person.name" @click="openDialog('task',{user_id:person.id})"><icon name="plus"/></button></div><article v-for="task in tasksFor(person.id)" :key="task.id" :class="['task-item',{done:task.is_completed}]"><button :class="['task-checkbox',{checked:task.is_completed}]" :aria-label="task.is_completed?'Повернути задачу: '+task.description:'Виконати задачу: '+task.description" :aria-pressed="task.is_completed" :disabled="saving" @click="toggleTask(task)"><icon v-if="task.is_completed" name="check"/></button><div class="task-copy"><h3>{{task.description}}</h3><div><span :class="['priority',task.priority]">{{priorityLabel(task.priority)}}</span><time v-if="task.task_time"><icon name="clock"/>{{task.task_time}}</time></div></div><button class="icon-button task-delete" :aria-label="'Видалити задачу: '+task.description" @click="openDialog('deleteTask',task)"><icon name="trash"/></button></article><div v-if="!tasksFor(person.id).length" class="empty-state compact"><span class="empty-icon"><icon name="check"/></span><h3>День відкритий для планів</h3><p>Додайте задачу або залиште час для себе.</p></div></article></section></div></template>
            <template v-if="view.name==='exchange'"><div v-if="rateError" class="notice error" role="alert">{{rateError}}</div><section class="panel exchange-panel"><div class="section-heading"><div><h2>Валютний калькулятор</h2><p>Змініть будь-яку суму — решту перерахуємо автоматично.</p></div><span class="surface-icon"><icon name="exchange"/></span></div><div class="currency-grid"><article v-for="currency in [{key:'cny',name:'Китайський юань',ticker:'CNY',symbol:'¥'},{key:'usd',name:'Tether',ticker:'USDT',symbol:'$'},{key:'uah',name:'Українська гривня',ticker:'UAH',symbol:'₴'}]" :key="currency.key" class="currency-card"><div class="currency-heading"><span>{{currency.symbol}}</span><div><h3>{{currency.ticker}}</h3><p>{{currency.name}}</p></div></div><label class="currency-input"><span>Сума {{currency.ticker}}</span><input v-model="exchange[currency.key]" :aria-label="'Сума '+currency.ticker" type="number" step="any" min="0" @input="recalculate(currency.key)"></label></article></div><div class="exchange-rates"><label class="field">Курс 1 CNY / USDT<input v-model="rates.cny_usdt" aria-label="Курс CNY до USDT" type="number" min="0.000001" step="any" @input="recalculate('cny')"></label><label class="field">Курс 1 USDT / UAH<input v-model="rates.usdt_uah" aria-label="Курс USDT до гривні" type="number" min="0.000001" step="any" @input="recalculate('usd')"></label><div class="exchange-note"><icon name="refresh"/><span>{{rateBusy?'Завантажуємо курси Coinbase…':rates.updated_at?'Курси Coinbase · '+dateLabel(rates.updated_at):'Курси можна ввести вручну'}}</span><small v-if="rates.usdt_cny">1 USDT = {{Number(rates.usdt_cny).toFixed(3)}} CNY</small></div></div></section></template>
            </template><footer class="page-footer"><span>Finance<span class="brand-dot"></span></span><span>Більше ясності у ваших фінансах</span></footer></main></div>
            <div v-if="notice" class="toast" role="status"><span><icon name="check"/></span>{{notice}}<button class="icon-button" aria-label="Закрити повідомлення" @click="notice=''"><icon name="close"/></button></div>
            <app-modal :open="Boolean(dialog)" :title="dialogTitle" :busy="saving" :error="formError" :danger="['deleteTask','deleteTransaction'].includes(dialog)" :confirm-label="['deleteTask','deleteTransaction'].includes(dialog)?'Так, видалити':undefined" @close="closeDialog" @save="save"><template v-if="dialog==='userTelegram'"><p class="dialog-description">{{form.name}}. Вкажіть числовий Telegram ID або очистіть поле, щоб відв’язати Telegram.</p><label class="field">Telegram ID<input v-model="form.telegram_id" type="text" inputmode="numeric" pattern="[1-9][0-9]{0,18}" maxlength="19" placeholder="Наприклад, 123456789"></label><p class="dialog-description">Свій ID можна отримати командою /start у боті. За автоматичним посиланням вводити його не потрібно.</p></template><template v-if="dialog==='year'"><p class="dialog-description">Новий рік — 12 місяців для ваших планів.</p><label class="field">Рік<input v-model="form.year" type="number" min="1900" max="9999" step="1" required></label></template><template v-if="dialog==='category'"><p class="dialog-description">{{form.id?'Оновіть назву — зміни відобразяться в бюджетах і транзакціях.':'Дайте категорії зрозумілу назву.'}}</p><label class="field">Назва категорії<input v-model="form.name" type="text" maxlength="255" placeholder="Наприклад, продукти" required></label></template><template v-if="dialog==='transaction'"><div class="form-grid"><label class="field span-two">Категорія<select v-model="form.category_id" required><option disabled value="">Оберіть категорію</option><option v-for="category in transactionCategories" :key="category.id" :value="category.id">{{category.name}}</option></select></label><label class="field span-two">Опис витрати<input v-model="form.title" type="text" placeholder="На що витратили?" maxlength="255" required></label><label class="field">Сума, грн<input v-model="form.amount" type="number" min="0" step="0.01" required></label><label class="field">Спосіб оплати<select v-model="form.type" required><option value="card">Картка</option><option value="cash">Готівка</option></select></label><label class="field span-two">Дата та час<input v-model="form.created_at" type="datetime-local" required></label></div></template><template v-if="dialog==='budget'"><label class="field">Категорія<select v-model="form.category_id" :disabled="Boolean(form.id)" required><option value="" disabled>Оберіть категорію</option><option v-for="category in availableCategories" :key="category.id" :value="category.id">{{category.name}}</option></select></label><p v-if="!availableCategories.length" class="dialog-description">Усі категорії вже мають бюджет або ще не створені. Додайте нову в розділі «Категорії».</p><label class="field">Бюджет, грн<input v-model="form.budget" type="number" min="0" step="0.01" required></label><div v-if="form.category_id" class="budget-suggestion"><icon name="arrow"/><div><span>Середні місячні витрати за цей рік</span><strong>{{analyticsLoading?'Розраховуємо…':analytics===null?'—':money(analytics)+' грн'}}</strong></div><button v-if="analytics!==null" class="button text" type="button" @click="form.budget=analytics">Використати</button></div></template><template v-if="dialog==='task'"><label class="field">Для кого<select v-model="form.user_id" required><option v-for="person in state.users" :key="person.id" :value="person.id">{{person.name}}</option></select></label><label class="field">Що потрібно зробити<textarea v-model="form.description" rows="3" maxlength="10000" required placeholder="Додайте свою задачу"></textarea></label><div class="form-grid"><label class="field">Пріоритет<select v-model="form.priority"><option value="high">Високий</option><option value="middle">Середній</option><option value="low">Низький</option></select></label><label class="field">Час<input v-model="form.task_time" type="time"></label><label class="field span-two">Дата<input v-model="form.task_date" type="date" required></label></div></template><template v-if="['deleteTask','deleteTransaction'].includes(dialog)"><p class="dialog-description">Ви впевнені, що хочете видалити {{dialog==='deleteTask'?'цю задачу':'цю транзакцію'}}?</p><div class="delete-summary"><strong>{{dialog==='deleteTask'?form.description:form.title}}</strong><span v-if="dialog==='deleteTransaction'">{{money(form.amount)}} грн</span></div><div class="notice warning">Запис буде видалено. Відновити його через кабінет буде неможливо.</div></template></app-modal>
        </div>`,
    };
    createApp(app).mount('#finance-app');
})();
